<template><main class="zj-workspace"><header class="zj-heading"><div><h1>公司与人员资料</h1><p>维护报告使用的资质原件，人员资料关联合同、项目与报账共用的员工档案。</p></div><el-button v-hasPermi="['management:credential:edit']" type="primary" @click="edit()">新增资料</el-button></header><section class="zj-card"><el-radio-group v-model="kind"><el-radio-button value="company">公司资料</el-radio-button><el-radio-button value="person">人员资料</el-radio-button></el-radio-group><el-input v-model="search" placeholder="搜索名称、人员或证书编号" clearable style="max-width:320px;margin:16px"/><el-table v-loading="loading" :data="filtered"><el-table-column prop="title" label="资质名称"/><el-table-column prop="holder" label="持有人 / 单位"/><el-table-column prop="certificateNo" label="证书编号"/><el-table-column label="有效期"><template #default="{row}"><el-tag :type="row.validUntil && row.validUntil<today?'danger':'info'">{{row.validUntil||'长期 / 未登记'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link v-hasPermi="['management:credential:edit']" @click="edit(row)">编辑及查看附件</el-button></template></el-table-column></el-table></section><el-drawer v-model="open" title="公司与人员资料" size="600px" :close-on-click-modal="false" :before-close="close"><el-form label-position="top"><el-form-item label="类型"><el-select v-model="form.kind"><el-option label="公司资料" value="company"/><el-option label="人员资料" value="person"/></el-select></el-form-item><el-form-item label="资质名称（必填）"><el-input v-model="form.title" maxlength="200"/></el-form-item><el-form-item v-if="form.kind==='person'" label="员工档案（必选）"><el-select v-model="form.employeeId" filterable remote :remote-method="findEmployees" @visible-change="v=>v&&findEmployees('')" placeholder="搜索姓名或类型"><el-option v-for="e in employees" :key="e.id" :value="e.id" :label="e.name+' · '+(e.employeeType||'')+' #'+e.id"/></el-select></el-form-item><el-form-item v-else label="所属单位"><el-input v-model="form.holder" maxlength="100"/></el-form-item><el-form-item label="资料类型"><el-radio-group v-model="form.valueType"><el-radio-button value="file">文件</el-radio-button><el-radio-button value="string">文字 / 编号</el-radio-button></el-radio-group></el-form-item><el-form-item v-if="form.valueType==='string'" label="文字内容"><el-input v-model="form.content" type="textarea" :rows="4" maxlength="20000"/></el-form-item><el-form-item label="证书编号"><el-input v-model="form.certificateNo" maxlength="100"/></el-form-item><el-form-item label="有效期至"><el-date-picker v-model="form.validUntil" value-format="YYYY-MM-DD"/></el-form-item><el-form-item v-if="form.valueType!=='string'" label="资料原件（按报告展示顺序上传）"><FileUpload v-model="form.files" :file-type="['pdf','png','jpg','jpeg']" :limit="20" :file-size="30"/></el-form-item></el-form><template #footer><el-button @click="close(()=>open=false)" :disabled="saving">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-drawer></main></template>
<script setup>
import "@/assets/styles/zhongji.scss";
import request from '@/utils/request';
const route=useRoute(),employees=ref([]);const {proxy}=getCurrentInstance();const rows=ref([]),loading=ref(false),saving=ref(false),open=ref(false),kind=ref('company'),search=ref(''),form=ref({});
let snapshot='';
async function close(done){if(saving.value)return;if(snapshot!==JSON.stringify(form.value)){try{await proxy.$modal.confirm('放弃未保存的资质修改？');}catch{return;}}done();}
onBeforeRouteLeave(async()=>{if(!open.value||snapshot===JSON.stringify(form.value))return true;try{await proxy.$modal.confirm('离开并放弃未保存的资质修改？');return true;}catch{return false;}});
const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());
const filtered=computed(()=>rows.value.filter(r=>r.kind===kind.value&&(!route.query.employeeId||r.employeeId===Number(route.query.employeeId))&&[r.title,r.holder,r.certificateNo].join(' ').includes(search.value)));
function edit(row){form.value=row?{...row}:{kind:kind.value,title:'',holder:'',employeeId:route.query.employeeId?Number(route.query.employeeId):null,valueType:'file',content:'',certificateNo:'',validUntil:null,files:''};employees.value=row?.employeeId?[{id:row.employeeId,name:row.holder}]:[];snapshot=JSON.stringify(form.value);open.value=true;}
async function load(){loading.value=true;try{rows.value=(await request({url:'/management/report-credentials'})).data;}finally{loading.value=false;}}
async function save(){if(!form.value.title.trim()||(form.value.valueType==='string'?!form.value.content?.trim():!form.value.files)||(form.value.kind==='person'&&!form.value.employeeId))return proxy.$modal.msgError('请填写名称、选择员工并填写内容或上传原件');saving.value=true;try{await request({url:'/management/report-credentials',method:'post',data:form.value});open.value=false;await load();proxy.$modal.msgSuccess('资质已保存');}finally{saving.value=false;}}
async function findEmployees(name){employees.value=(await request({url:'/management/employees/options',params:{name}})).data}
onMounted(()=>{if(route.query.employeeId)kind.value='person';load()});
</script>
